/**
 * This class facilitates interaction with Coordinator/Overlord leader nodes. Instance of this class is injected
 * via Guice with annotations @Coordinator or @IndexingService .
 * Usage:
 * Request request = druidLeaderClient.makeRequest(HttpMethod, requestPath)
 * request.setXXX(..)
 * FullResponseHolder responseHolder = druidLeaderClient.go(request)
 */
public class DruidLeaderClient
{
  private final Logger log = new Logger(DruidLeaderClient.class);

  private static final int MAX_RETRIES = 5;

  private final HttpClient httpClient;
  private final DruidNodeDiscoveryProvider druidNodeDiscoveryProvider;
  private final NodeRole nodeRoleToWatch;

  private final String leaderRequestPath;

  private LifecycleLock lifecycleLock = new LifecycleLock();
  private DruidNodeDiscovery druidNodeDiscovery;
  private AtomicReference<String> currentKnownLeader = new AtomicReference<>();

  private final Logger indexerLog = new Logger(HttpIndexingServiceClient.class);

  private String lastCoordinatorDataSource;
  private String lastCoordinatorPath;
  private int lastCoordinatorStatusCode;
  private String lastCoordinatorSnippet;

  private String lastIndexerTaskId;
  private String lastIndexerPath;
  private int lastIndexerStatusCode;
  private int lastIndexerWorkerCapacity;

  private String lastLookupTier;
  private int lastLookupStatusCode;
  private boolean lastLookupLegacyList;
  private String lastLookupSnippet;

  private String lastHandoffDataSource;
  private String lastHandoffVersion;
  private int lastHandoffPartition;
  private int lastHandoffMatchCount;

  private String lastPickedScheme;
  private String lastPickedHost;
  private String lastPickedRole;
  private int lastPickedServiceCount;


  public DruidLeaderClient(
      HttpClient httpClient,
      DruidNodeDiscoveryProvider druidNodeDiscoveryProvider,
      NodeRole nodeRoleToWatch,
      String leaderRequestPath
  )
  {
    this.httpClient = httpClient;
    this.druidNodeDiscoveryProvider = druidNodeDiscoveryProvider;
    this.nodeRoleToWatch = nodeRoleToWatch;
    this.leaderRequestPath = leaderRequestPath;
  }

  @LifecycleStart
  public void start()
  {
    if (!lifecycleLock.canStart()) {
      throw new ISE("can't start.");
    }

    try {
      druidNodeDiscovery = druidNodeDiscoveryProvider.getForNodeRole(nodeRoleToWatch);
      lifecycleLock.started();
      log.debug("Started.");
    }
    finally {
      lifecycleLock.exitStart();
    }
  }

  @LifecycleStop
  public void stop()
  {
    if (!lifecycleLock.canStop()) {
      throw new ISE("can't stop.");
    }

    log.debug("Stopped.");
  }

  /**
   * Make a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public Request makeRequest(HttpMethod httpMethod, String urlPath) throws IOException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    return new Request(httpMethod, new URL(StringUtils.format("%s%s", getCurrentKnownLeader(true), urlPath)));
  }

  public StringFullResponseHolder go(Request request) throws IOException, InterruptedException
  {
    return go(request, new StringFullResponseHandler(StandardCharsets.UTF_8));
  }

  /**
   * Executes a Request object aimed at the leader. Throws IOException if the leader cannot be located.
   */
  public <T, H extends FullResponseHolder<T>> H go(Request request, HttpResponseHandler<H, H> responseHandler)
      throws IOException, InterruptedException
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    for (int counter = 0; counter < MAX_RETRIES; counter++) {

      final H fullResponseHolder;

      try {
        try {
          fullResponseHolder = httpClient.go(request, responseHandler).get();
        }
        catch (ExecutionException e) {
          // Unwrap IOExceptions and ChannelExceptions, re-throw others
          Throwables.propagateIfInstanceOf(e.getCause(), IOException.class);
          Throwables.propagateIfInstanceOf(e.getCause(), ChannelException.class);
          throw new RE(e, "HTTP request to[%s] failed", request.getUrl());
        }
      }
      catch (IOException | ChannelException ex) {
        // can happen if the node is stopped.
        log.warn(ex, "Request[%s] failed.", request.getUrl());

        try {
          if (request.getUrl().getQuery() == null) {
            request = withUrl(
                request,
                new URL(StringUtils.format("%s%s", getCurrentKnownLeader(false), request.getUrl().getPath()))
            );
          } else {
            request = withUrl(
                request,
                new URL(StringUtils.format(
                    "%s%s?%s",
                    getCurrentKnownLeader(false),
                    request.getUrl().getPath(),
                    request.getUrl().getQuery()
                ))
            );
          }
          continue;
        }
        catch (MalformedURLException e) {
          // Not an IOException; this is our own fault.
          throw new ISE(
              e,
              "failed to build url with path[%] and query string [%s].",
              request.getUrl().getPath(),
              request.getUrl().getQuery()
          );
        }
      }

      if (HttpResponseStatus.TEMPORARY_REDIRECT.equals(fullResponseHolder.getResponse().getStatus())) {
        String redirectUrlStr = fullResponseHolder.getResponse().headers().get("Location");
        if (redirectUrlStr == null) {
          throw new IOE("No redirect location is found in response from url[%s].", request.getUrl());
        }

        log.info("Request[%s] received redirect response to location [%s].", request.getUrl(), redirectUrlStr);

        final URL redirectUrl;
        try {
          redirectUrl = new URL(redirectUrlStr);
        }
        catch (MalformedURLException ex) {
          throw new IOE(
              ex,
              "Malformed redirect location is found in response from url[%s], new location[%s].",
              request.getUrl(),
              redirectUrlStr
          );
        }

        //update known leader location
        currentKnownLeader.set(StringUtils.format(
            "%s://%s:%s",
            redirectUrl.getProtocol(),
            redirectUrl.getHost(),
            redirectUrl.getPort()
        ));

        request = withUrl(request, redirectUrl);
      } else {
        return fullResponseHolder;
      }
    }

    throw new IOE("Retries exhausted, couldn't fulfill request to [%s].", request.getUrl());
  }

  public String findCurrentLeader()
  {
    Preconditions.checkState(lifecycleLock.awaitStarted(1, TimeUnit.MILLISECONDS));
    final StringFullResponseHolder responseHolder;
    try {
      responseHolder = go(makeRequest(HttpMethod.GET, leaderRequestPath));
    }
    catch (Exception ex) {
      throw new ISE(ex, "Couldn't find leader.");
    }

    if (responseHolder.getStatus().getCode() == 200) {
      String leaderUrl = responseHolder.getContent();

      //verify this is valid url
      try {
        URL validatedUrl = new URL(leaderUrl);
        currentKnownLeader.set(leaderUrl);

        // validatedUrl.toString() is returned instead of leaderUrl or else teamcity build fails because of breaking
        // the rule of ignoring new URL(leaderUrl) object.
        return validatedUrl.toString();
      }
      catch (MalformedURLException ex) {
        log.error(ex, "Received malformed leader url[%s].", leaderUrl);
      }
    }

    throw new ISE(
        "Couldn't find leader, failed response status is [%s] and content [%s].",
        responseHolder.getStatus().getCode(),
        responseHolder.getContent()
    );
  }

  private String getCurrentKnownLeader(final boolean cached) throws IOException
  {
    final String leader = currentKnownLeader.accumulateAndGet(
        null,
        (current, given) -> current == null || !cached ? pickOneHost() : current
    );

    if (leader == null) {
      throw new IOE("No known server");
    } else {
      return leader;
    }
  }

  @Nullable
  private String pickOneHost()
  {
    Iterator<DiscoveryDruidNode> iter = druidNodeDiscovery.getAllNodes().iterator();
    if (iter.hasNext()) {
      DiscoveryDruidNode node = iter.next();
      recordPickedNode(node);
      return leaderUriFromNode(node);
    }

    return null;
  }

  private Request withUrl(Request old, URL url)
  {
    return copyRequestPreservingHeaders(old, url);
  }

  private boolean requestHasBody(Request request)
  {
    return request.hasContent();
  }

  private Request newRequestWithMethod(Request old, URL url)
  {
    return new Request(old.getMethod(), url);
  }

  private Request copyHeadersOnto(Request dest, Request source)
  {
    dest.addHeaderValues(source.getHeaders());
    return dest;
  }

  private Request copyBodyOnto(Request dest, Request source)
  {
    if (requestHasBody(source)) {
      dest.setContent(source.getContent());
    }
    return dest;
  }


  static String encodePathSegment(String raw)
  {
    return StringUtils.urlEncode(raw);
  }

  static boolean isOkStatus(HttpResponseStatus status)
  {
    return HttpResponseStatus.OK.equals(status);
  }

  static boolean isNotFoundStatus(HttpResponseStatus status)
  {
    return HttpResponseStatus.NOT_FOUND.equals(status);
  }

  static int httpStatusCode(HttpResponseStatus status)
  {
    return status.getCode();
  }

  static String snippetContent(String content)
  {
    if (content == null) {
      return "";
    }
    if (content.length() <= 512) {
      return content;
    }
    return content.substring(0, 512);
  }

  static String replaceIntervalSlashes(Interval interval)
  {
    return interval.toString().replace('/', '_');
  }

  static boolean startsWithJsonArray(String content)
  {
    return content.startsWith("[");
  }

  static String formatLeaderUri(String scheme, String hostAndPort)
  {
    return StringUtils.format("%s://%s", scheme, hostAndPort);
  }

  static String buildQueryString(String[] keys, Object[] values)
  {
    final StringBuilder sb = new StringBuilder(64);
    for (int i = 0; i < keys.length; i++) {
      if (i > 0) {
        sb.append('&');
      }
      sb.append(keys[i]).append('=');
      if (values[i] == null) {
        sb.append("null");
      } else {
        sb.append(values[i]);
      }
    }
    return sb.toString();
  }

  static String joinPath(String... parts)
  {
    final StringBuilder sb = new StringBuilder(64);
    for (int i = 0; i < parts.length; i++) {
      String part = parts[i];
      if (i == 0) {
        sb.append(part);
        continue;
      }
      if (part.startsWith("/")) {
        sb.append(part);
      } else {
        sb.append('/').append(part);
      }
    }
    return sb.toString();
  }

  static boolean isEmptyContent(String content)
  {
    return content == null || content.length() == 0;
  }

  static String jsonContentType()
  {
    return MediaType.APPLICATION_JSON;
  }

  static Object firstOrNull(List<?> values)
  {
    if (values == null) {
      return null;
    }
    if (values.isEmpty()) {
      return null;
    }
    return values.get(0);
  }

  static int collectionSize(Collection<?> values)
  {
    if (values == null) {
      return 0;
    }
    return values.size();
  }

  static int mapSize(Map<?, ?> values)
  {
    if (values == null) {
      return 0;
    }
    return values.size();
  }

  static boolean safeEquals(Object left, Object right)
  {
    if (left == null) {
      return right == null;
    }
    return left.equals(right);
  }

  static String contentOrEmpty(String content)
  {
    if (content == null) {
      return "";
    }
    return content;
  }

  static String formatAbsolutePath(String prefix, String encoded)
  {
    return StringUtils.format("%s/%s", prefix, encoded);
  }

  static boolean isRedirectStatus(HttpResponseStatus status)
  {
    return HttpResponseStatus.TEMPORARY_REDIRECT.equals(status);
  }

  static String methodName(HttpMethod method)
  {
    return method.getName();
  }

  static int safeLength(String value)
  {
    if (value == null) {
      return 0;
    }
    return value.length();
  }

  static String booleanQueryValue(boolean value)
  {
    return Boolean.toString(value);
  }


  static String renderEncodedDatasourcePath(String prefix, String dataSource, String suffix)
  {
    final String encoded = encodePathSegment(dataSource);
    final String joined = joinPath(prefix, encoded);
    if (suffix.isEmpty()) {
      return joined;
    }
    if (suffix.startsWith("/") || suffix.startsWith("?")) {
      return joined + suffix;
    }
    return joinPath(joined, suffix);
  }

  static String renderTaskResourcePath(String taskId, String resource)
  {
    final String encoded = encodePathSegment(taskId);
    if (resource == null || resource.isEmpty()) {
      return StringUtils.format("/druid/indexer/v1/task/%s", encoded);
    }
    return StringUtils.format("/druid/indexer/v1/task/%s/%s", encoded, resource);
  }

  static String renderIndexerCollectionPath(String collection)
  {
    return StringUtils.format("/druid/indexer/v1/%s", collection);
  }

  static String extractStringField(Map<String, Object> map, String key)
  {
    final Object value = map.get(key);
    if (value == null) {
      return null;
    }
    return String.valueOf(value);
  }

  static int extractIntField(Map<String, Object> map, String key, int defaultValue)
  {
    final Object value = map.get(key);
    if (value == null) {
      return defaultValue;
    }
    if (value instanceof Number) {
      return ((Number) value).intValue();
    }
    return Integer.parseInt(String.valueOf(value));
  }

  static List<String> collectTaskIds(Iterable<TaskStatusPlus> tasks)
  {
    final List<String> ids = new ArrayList<>();
    for (TaskStatusPlus task : tasks) {
      if (task != null && task.getId() != null) {
        ids.add(task.getId());
      }
    }
    return ids;
  }

  static List<TaskStatusPlus> dedupeTasksById(Iterable<TaskStatusPlus> tasks)
  {
    final List<TaskStatusPlus> result = new ArrayList<>();
    final Set<String> seen = new HashSet<>();
    for (TaskStatusPlus task : tasks) {
      if (task == null) {
        continue;
      }
      if (seen.add(task.getId())) {
        result.add(task);
      }
    }
    return result;
  }

  static int sumPositiveCapacities(Collection<IndexingWorkerInfo> workers)
  {
    int total = 0;
    for (IndexingWorkerInfo workerInfo : workers) {
      total += workerInfo.getWorker().getCapacity();
    }
    return total;
  }

  static boolean allSegmentsShareDataSource(List<DataSegment> segments, String dataSource)
  {
    for (DataSegment segment : segments) {
      if (!dataSource.equals(segment.getDataSource())) {
        return false;
      }
    }
    return true;
  }

  static Interval[] collectSegmentIntervals(List<DataSegment> segments)
  {
    final Interval[] intervals = new Interval[segments.size()];
    for (int i = 0; i < segments.size(); i++) {
      intervals[i] = segments.get(i).getInterval();
    }
    return intervals;
  }


  static String renderPendingSegmentsPath(String dataSource, Interval interval)
  {
    return StringUtils.format(
        "/druid/indexer/v1/pendingSegments/%s?interval=%s",
        encodePathSegment(dataSource),
        interval
    );
  }

  static String renderLookupConfigPath(String tier)
  {
    return StringUtils.format("/druid/coordinator/v1/lookups/config/%s?detailed=true", encodePathSegment(tier));
  }

  static String renderUsedSegmentsPath(String dataSource)
  {
    return StringUtils.format(
        "/druid/coordinator/v1/metadata/datasources/%s/segments?full",
        encodePathSegment(dataSource)
    );
  }

  static String renderUsedSegmentPath(String dataSource, String segmentId)
  {
    return StringUtils.format(
        "/druid/coordinator/v1/metadata/datasources/%s/segments/%s",
        encodePathSegment(dataSource),
        encodePathSegment(segmentId)
    );
  }

  static String renderServerViewPath(String dataSource, Interval interval, boolean incompleteOk)
  {
    return StringUtils.format(
        "/druid/coordinator/v1/datasources/%s/intervals/%s/serverview?partial=%s",
        encodePathSegment(dataSource),
        replaceIntervalSlashes(interval),
        booleanQueryValue(incompleteOk)
    );
  }

  static String renderHandoffCompletePath(String dataSource, SegmentDescriptor descriptor)
  {
    final String[] keys = new String[]{"interval", "partitionNumber", "version"};
    final Object[] values = new Object[]{
        descriptor.getInterval(),
        descriptor.getPartitionNumber(),
        descriptor.getVersion()
    };
    return renderEncodedDatasourcePath(
        "/druid/coordinator/v1/datasources",
        dataSource,
        "handoffComplete?" + buildQueryString(keys, values)
    );
  }

  static boolean segmentMatchesHandoff(ImmutableSegmentLoadInfo loadInfo, SegmentDescriptor descriptor)
  {
    if (!loadInfo.getSegment().getInterval().contains(descriptor.getInterval())) {
      return false;
    }
    if (loadInfo.getSegment().getShardSpec().getPartitionNum() != descriptor.getPartitionNumber()) {
      return false;
    }
    if (loadInfo.getSegment().getVersion().compareTo(descriptor.getVersion()) < 0) {
      return false;
    }
    return loadInfo.getServers().stream().anyMatch(DruidServerMetadata::isSegmentReplicationOrBroadcastTarget);
  }

  static String hostAndPortOf(DiscoveryDruidNode node)
  {
    return node.getDruidNode().getHostAndPortToUse();
  }

  static String serviceSchemeOf(DiscoveryDruidNode node)
  {
    return node.getDruidNode().getServiceScheme();
  }

  static String nodeRoleString(DiscoveryDruidNode node)
  {
    return node.getNodeRole().toString();
  }


  static Map<String, Object> copyStringObjectMap(Map<String, Object> source)
  {
    if (source == null) {
      return Collections.emptyMap();
    }
    final Map<String, Object> copy = new HashMap<>();
    for (Map.Entry<String, Object> entry : source.entrySet()) {
      copy.put(entry.getKey(), entry.getValue());
    }
    return copy;
  }

  static List<String> keysOf(Map<String, ?> source)
  {
    if (source == null || source.isEmpty()) {
      return Collections.emptyList();
    }
    final List<String> keys = new ArrayList<>(source.size());
    for (String key : source.keySet()) {
      keys.add(key);
    }
    return keys;
  }

  static String joinNonNull(String delimiter, String... parts)
  {
    final StringBuilder sb = new StringBuilder();
    for (int i = 0; i < parts.length; i++) {
      if (parts[i] == null) {
        continue;
      }
      if (sb.length() > 0) {
        sb.append(delimiter);
      }
      sb.append(parts[i]);
    }
    return sb.toString();
  }


  static int countSlashes(String path)
  {
    if (path == null || path.isEmpty()) {
      return 0;
    }
    int count = 0;
    for (int i = 0; i < path.length(); i++) {
      if (path.charAt(i) == '/') {
        count++;
      }
    }
    return count;
  }

  static int countQuerySeparators(String path)
  {
    if (path == null || path.isEmpty()) {
      return 0;
    }
    int count = 0;
    for (int i = 0; i < path.length(); i++) {
      char c = path.charAt(i);
      if (c == '?' || c == '&' || c == '=') {
        count++;
      }
    }
    return count;
  }

  static boolean pathLooksAbsolute(String path)
  {
    if (path == null || path.isEmpty()) {
      return false;
    }
    return path.charAt(0) == '/';
  }

  static String lastPathSegment(String path)
  {
    if (path == null || path.isEmpty()) {
      return "";
    }
    int queryAt = path.indexOf('?');
    String withoutQuery = queryAt < 0 ? path : path.substring(0, queryAt);
    int slash = withoutQuery.lastIndexOf('/');
    if (slash < 0 || slash == withoutQuery.length() - 1) {
      return withoutQuery;
    }
    return withoutQuery.substring(slash + 1);
  }

  static boolean containsEncodedSpace(String value)
  {
    if (value == null || value.isEmpty()) {
      return false;
    }
    return value.contains("%20") || value.contains("+");
  }

  static int intervalMillis(Interval interval)
  {
    if (interval == null) {
      return 0;
    }
    long millis = interval.toDurationMillis();
    if (millis > Integer.MAX_VALUE) {
      return Integer.MAX_VALUE;
    }
    if (millis < Integer.MIN_VALUE) {
      return Integer.MIN_VALUE;
    }
    return (int) millis;
  }

  static boolean intervalIsEmpty(Interval interval)
  {
    return interval != null && interval.toDurationMillis() == 0;
  }

  static String describeStatus(HttpResponseStatus status)
  {
    if (status == null) {
      return "null";
    }
    return StringUtils.format("%s:%s", status.getCode(), status.getReasonPhrase());
  }

  static boolean isAsciiLetterOrDigit(char c)
  {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
  }

  static int countUnreserved(String value)
  {
    if (value == null || value.isEmpty()) {
      return 0;
    }
    int count = 0;
    for (int i = 0; i < value.length(); i++) {
      if (isAsciiLetterOrDigit(value.charAt(i))) {
        count++;
      }
    }
    return count;
  }


