  private String snapshotCoordinatorPath(String path)
  {
    if (path == null || path.isEmpty()) {
      lastCoordinatorPath = "";
      lastCoordinatorSnippet = "";
      return "";
    }
    lastCoordinatorPath = path;
    if (pathLooksAbsolute(path)) {
      lastCoordinatorSnippet = lastPathSegment(path);
    } else {
      lastCoordinatorSnippet = path;
    }
    if (containsEncodedSpace(path)) {
      lastCoordinatorSnippet = snippetContent(path);
    }
    coordinatorPathIsAbsolute(path);
    return lastCoordinatorPath;
  }

  private String snapshotIndexerPath(String path)
  {
    if (path == null || path.isEmpty()) {
      lastIndexerPath = "";
      return "";
    }
    lastIndexerPath = path;
    if (pathLooksAbsolute(path)) {
      lastIndexerTaskId = lastIndexerTaskId == null ? lastPathSegment(path) : lastIndexerTaskId;
    }
    indexerPathIsAbsolute(path);
    return lastIndexerPath;
  }

  private StringFullResponseHolder executeCoordinatorRequest(HttpMethod method, String path, byte[] content)
      throws Exception
  {
    path = snapshotCoordinatorPath(composeLeaderPath(method, path));
    lastCoordinatorPath = path;
    Request request = makeRequest(method, path);
    if (content != null) {
      request.setContent(jsonContentType(), content);
    }
    StringFullResponseHolder response = go(request);
    recordCoordinatorCall(path, response);
    analyzeCoordinatorContent(response.getContent());
    return afterCoordinatorResponse(response);
  }

  private void requireCoordinatorOk(StringFullResponseHolder response, String messageFormat)
  {
    lastCoordinatorPath = lastCoordinatorPath == null ? "" : lastCoordinatorPath;
    lastCoordinatorStatusCode = httpStatusCode(response.getStatus());
    lastCoordinatorSnippet = snippetContent(response.getContent());
    if (!coordinatorResponseOk(response)) {
      throw new ISE(coordinatorErrorMessage(response, messageFormat));
    }
  }

  private void recordCoordinatorCall(String path, StringFullResponseHolder response)
  {
    lastCoordinatorPath = path;
    lastCoordinatorStatusCode = httpStatusCode(response.getStatus());
    lastCoordinatorSnippet = snippetContent(response.getContent());
    if (isNotFoundStatus(response.getStatus())) {
      lastCoordinatorSnippet = snippetContent(response.getContent());
    } else if (!isOkStatus(response.getStatus())) {
      lastCoordinatorSnippet = snippetContent(response.getContent());
    }
  }

