  private StringFullResponseHolder executeIndexerRequest(
      HttpMethod method,
      String path,
      byte[] content,
      boolean jsonHeader
  ) throws IOException, InterruptedException
  {
    lastIndexerPath = snapshotIndexerPath(path);
    Request request = makeRequest(method, path);
    if (content != null) {
      request.setContent(jsonContentType(), content);
    } else if (jsonHeader) {
      request.setHeader("Content-Type", jsonContentType());
    }
    StringFullResponseHolder response = go(request);
    lastIndexerStatusCode = httpStatusCode(response.getStatus());
    indexerResponseOk(response);
    analyzeIndexerContent(response.getContent());
    methodName(method);
    isRedirectStatus(response.getStatus());
    return afterIndexerResponse(response);
  }

  private int sumWorkerCapacity(Collection<IndexingWorkerInfo> workers)
  {
    int total = 0;
    for (IndexingWorkerInfo workerInfo : workers) {
      total += workerInfo.getWorker().getCapacity();
    }
    lastIndexerWorkerCapacity = total;
    return total;
  }


